  /// One of `pt-BR`.
  final String locale;

  /// The party whose capture it is.
  final String partyId;

  /// Why the person is asked again, as reason codes (document.recapture,
  /// evidence.incomplete, review.recapture, review.information); empty on a
  /// first capture.
  final List<String> reasons;

  final String? returnUrl;

  final String? revokedAt;

  /// active while the link opens; finished once the person sent the capture;
  /// revoked when withdrawn or replaced by a newer link; expired past
  /// expires_at.
  ///
  /// One of `active`, `finished`, `revoked`, `expired`.
  final String status;

  /// What the link asks for, in order, chosen from the workflow version the
  /// case is pinned to.
  final List<String> steps;

  /// The token, kc_ and 43 characters, shown this once; only its SHA-256 is
  /// stored. null on a replay.
  final String? token;

  /// The link to send the person: the application's address, /c/ and the token.
  /// null on a replay.
  final String? url;

  final CaptureSessionWorkflow workflow;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'case_id': caseId,
    'completed_steps': completedSteps,
    'created_at': createdAt,
    'email_status': emailStatus,
    'embed_origin': ?embedOrigin,
    'expires_at': expiresAt,
    'finished_at': ?finishedAt,
    'handoff': ?handoff,
    'id': id,
    'locale': locale,
    'party_id': partyId,
    'reasons': reasons,
    'return_url': ?returnUrl,
    'revoked_at': ?revokedAt,
    'status': status,
    'steps': steps,
    'token': token,
    'url': url,
    'workflow': workflow.toJson(),
  };
}

