/// CaptureSessionRequest is a request body of KUAA's API.
final class CaptureSessionRequest {
  const CaptureSessionRequest({
    this.email,
    this.embedOrigin,
    this.expiresInMinutes,
    this.handoff,
    this.partyId,
    this.returnUrl,
    this.sendEmail,
  });

  /// The address to e-mail the link to, instead of the one on file. Given
  /// alone, it asks for the e-mail too. It is not stored and not audited: the
  /// audit keeps only that a link was e-mailed.
  final String? email;

  /// The one https origin that may frame the capture (iframe or WebView) and
  /// receive its postMessage events. Without it the capture refuses to be
  /// framed.
  final String? embedOrigin;

  /// How long the link opens, in minutes. Default 1440 (one day).
  final int? expiresInMinutes;

  /// How the link, opened on a desktop, offers itself on a phone: `never` shows
  /// the capture on any device; `suggest` shows it with a QR code of the same
  /// link to continue on a phone; `require` shows a desktop only the QR code.
  /// Omitted, the organization's setting applies (suggest by default). The
  /// device is read from what the browser says about itself: it steers the page
  /// and is not a security control.
  ///
  /// One of `never`, `suggest`, `require`.
  final String? handoff;

  /// The party whose capture this is. Empty is the case's primary party.
  final String? partyId;

  /// Where the person is offered to go back to when they finish: an absolute
  /// https:// address.
  final String? returnUrl;

  /// E-mail the link to the person, in Portuguese and under the organization's
  /// brand: to email when given, to the e-mail on file for the party otherwise.
  /// A link issued after the case was sent back is e-mailed as a request to
  /// send again, with the reason in plain words. At most 5 e-mails per case in
  /// 24 hours; data.email_status says what happened, and the link is issued
  /// either way.
  final bool? sendEmail;

  /// The JSON the API takes; a field left null is left out.
  Map<String, Object?> toJson() => {
    'email': ?email,
    'embed_origin': ?embedOrigin,
    'expires_in_minutes': ?expiresInMinutes,
    'handoff': ?handoff,
    'party_id': ?partyId,
    'return_url': ?returnUrl,
    'send_email': ?sendEmail,
  };
}

