/// Case is an object of KUAA's API.
final class Case {
  const Case({
    this.childGroup,
    required this.createdAt,
    required this.currentState,
    this.customStatus,
    required this.externalReference,
    required this.id,
    required this.kind,
    required this.livemode,
    this.parentCaseId,
    required this.parties,
    this.policyVersionId,
    required this.relationships,
    required this.status,
    required this.statusMarket,
    required this.updatedAt,
    this.workflowDefinitionId,
  });

  /// A Case out of the API's JSON.
  factory Case.fromJson(Map<String, Object?> json) {
    return Case(
      childGroup: json['child_group'] as String?,
      createdAt: json['created_at'] as String,
      currentState: json['current_state'] as String,
      customStatus: readOptional(
        json['custom_status'],
        (value) => CustomStatus.fromJson(readObject(value)),
      ),
      externalReference: json['external_reference'] as String,
      id: json['id'] as String,
      kind: json['kind'] as String,
      livemode: json['livemode'] as bool,
      parentCaseId: json['parent_case_id'] as String?,
      parties: readList(
        json['parties'],
        (value) => Party.fromJson(readObject(value)),
      ),
      policyVersionId: json['policy_version_id'] as String?,
      relationships: readList(
        json['relationships'],
        (value) => Relationship.fromJson(readObject(value)),
      ),
      status: json['status'] as String,
      statusMarket: json['status_market'] as String,
      updatedAt: json['updated_at'] as String,
      workflowDefinitionId: json['workflow_definition_id'] as String?,
    );
  }

  /// On a child case, the children state of the parent's workflow that opened
  /// it, such as kyc; the parent's policy reads the children's outcomes as the
  /// facts children.&lt;child_group&gt;.*. Null on a case the client opened.
  final String? childGroup;

  final String createdAt;

  /// The workflow state the case is in.
  final String currentState;

  /// The label of the organization's own set of situations a reviewer gave the
  /// case, such as "Aguardando compliance". It never changes status,
  /// status_market or the decision. Null when the case carries none, or for a
  /// key without tag.list.
  final CustomStatus? customStatus;

  final String externalReference;

  /// The case identifier, used in every /v1/cases/{id} path.
  final String id;

  /// One of `KYC`, `KYB`, `AGE`.
  final String kind;

  /// False when the answer comes from the organization's sandbox: synthetic
  /// data, engine doubles chosen by the documented magic values, nothing billed
  /// and no official source consulted. True in production.
  final bool livemode;

  /// On a child case, the case whose workflow opened it: a KYB opens one KYC
  /// case per beneficial owner and administrator when it runs br.kyb v3. Null
  /// on a case the client opened.
  final String? parentCaseId;

  final List<Party> parties;

  final String? policyVersionId;

  final List<Relationship> relationships;

  /// One of `open`, `processing`, `awaiting_input`, `in_review`, `approved`,
  /// `rejected`, `cancelled`, `expired`.
  final String status;

  /// The status in the vocabulary of the Brazilian KYC market, beside status,
  /// which keeps its values: PROCESSING (open, processing, awaiting_input),
  /// PENDING_OCR (in_review because a document reading check -- OCR or
  /// validation -- failed or timed out), PENDING (in_review, waiting for a
  /// human decision), APPROVED (approved), REPROVED (rejected), BLOCKED
  /// (rejected by the policy's block outcome, such as a confirmed sanctions
  /// match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED
  /// are closed without a decision. It never changes the decision.
  ///
  /// One of `PROCESSING`, `PENDING_OCR`, `PENDING`, `APPROVED`, `REPROVED`,
  /// `BLOCKED`, `CANCELLED`, `EXPIRED`.
  final String statusMarket;

  final String updatedAt;

  final String? workflowDefinitionId;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'child_group': childGroup,
    'created_at': createdAt,
    'current_state': currentState,
    'custom_status': customStatus?.toJson(),
    'external_reference': externalReference,
    'id': id,
    'kind': kind,
    'livemode': livemode,
    'parent_case_id': parentCaseId,
    'parties': parties.map((item) => item.toJson()).toList(),
    'policy_version_id': policyVersionId,
    'relationships': relationships.map((item) => item.toJson()).toList(),
    'status': status,
    'status_market': statusMarket,
    'updated_at': updatedAt,
    'workflow_definition_id': workflowDefinitionId,
  };
}

