/// CaseRequestParty is a request body of KUAA's API.
final class CaseRequestParty {
  const CaseRequestParty({
    this.birthDate,
    this.cnae,
    this.cnpj,
    this.cpf,
    this.email,
    this.fullName,
    required this.kind,
    this.naturezaJuridica,
    this.nomeFantasia,
    this.phone,
    this.postalCode,
    this.primary,
    this.razaoSocial,
    this.situacao,
    this.socialName,
  });

  /// The birth date of a PERSON, as YYYY-MM-DD.
  final String? birthDate;

  /// The main CNAE activity code of a BUSINESS.
  final String? cnae;

  /// The CNPJ of a BUSINESS, as text, with or without punctuation. It is
  /// alphanumeric: twelve characters from 0-9 and A-Z followed by two check
  /// digits, stored normalized as ^[0-9A-Z]{12}[0-9]{2}$. Required for a
  /// BUSINESS and refused for a PERSON.
  final String? cnpj;

  /// The CPF of a PERSON, as text, with or without punctuation; it is stored as
  /// its 11 digits. Required for a PERSON and refused for a BUSINESS.
  final String? cpf;

  /// A contact e-mail address. Stored encrypted and never answered back.
  final String? email;

  /// The civil name of a PERSON. Required for a PERSON.
  final String? fullName;

  /// PERSON is identified by CPF, BUSINESS by CNPJ.
  ///
  /// One of `PERSON`, `BUSINESS`.
  final String kind;

  /// The legal nature code of a BUSINESS.
  final String? naturezaJuridica;

  /// The trade name of a BUSINESS.
  final String? nomeFantasia;

  /// A Brazilian telephone number, with or without +55 and punctuation. Stored
  /// encrypted and never answered back.
  final String? phone;

  /// A CEP, with or without punctuation. Stored encrypted and never answered
  /// back.
  final String? postalCode;

  /// Whether the party is the primary subject of the case. At most one party
  /// is.
  final bool? primary;

  /// The registered name of a BUSINESS. Required for a BUSINESS.
  final String? razaoSocial;

  /// The registration status of a BUSINESS, as the client knows it.
  final String? situacao;

  /// The social name of a PERSON, when there is one.
  final String? socialName;

  /// The JSON the API takes; a field left null is left out.
  Map<String, Object?> toJson() => {
    'birth_date': ?birthDate,
    'cnae': ?cnae,
    'cnpj': ?cnpj,
    'cpf': ?cpf,
    'email': ?email,
    'full_name': ?fullName,
    'kind': kind,
    'natureza_juridica': ?naturezaJuridica,
    'nome_fantasia': ?nomeFantasia,
    'phone': ?phone,
    'postal_code': ?postalCode,
    'primary': ?primary,
    'razao_social': ?razaoSocial,
    'situacao': ?situacao,
    'social_name': ?socialName,
  };
}

