/// ChipRead is an object of KUAA's API.
final class ChipRead {
  const ChipRead({
    required this.check,
    required this.checkId,
    required this.dg2Present,
    required this.evidenceId,
    this.faceEvidenceId,
    required this.outcomes,
    required this.reasons,
    required this.result,
  });

  /// A ChipRead out of the API's JSON.
  factory ChipRead.fromJson(Map<String, Object?> json) {
    return ChipRead(
      check: json['check'] as String,
      checkId: json['check_id'] as String,
      dg2Present: json['dg2_present'] as bool,
      evidenceId: json['evidence_id'] as String,
      faceEvidenceId: json['face_evidence_id'] as String?,
      outcomes: ChipOutcomes.fromJson(readObject(json['outcomes'])),
      reasons: readMap(json['reasons'], readString),
      result: json['result'] as String,
    );
  }

  /// One of `document_chip`.
  final String check;

  /// The document_chip check the read was recorded as.
  final String checkId;

  /// The chip gave a face image.
  final bool dg2Present;

  /// The evidence of the examination.
  final String evidenceId;

  /// The evidence of the comparison of the face image with the latest selfie,
  /// null when none ran.
  final String? faceEvidenceId;

  /// Each outcome of the read, the fact chip.&lt;name&gt; a policy reads.
  /// unverifiable is never a pass.
  final ChipOutcomes outcomes;

  /// The machine-readable reason of each outcome that is not a plain pass, such
  /// as no_trust_store or hash_mismatch.
  final Map<String, String> reasons;

  /// fail when an outcome failed, pass when Passive Authentication passed and
  /// nothing failed, inconclusive otherwise. A measurement, never an approval:
  /// the policy decides.
  ///
  /// One of `pass`, `fail`, `inconclusive`.
  final String result;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'check': check,
    'check_id': checkId,
    'dg2_present': dg2Present,
    'evidence_id': evidenceId,
    'face_evidence_id': faceEvidenceId,
    'outcomes': outcomes.toJson(),
    'reasons': reasons,
    'result': result,
  };
}

/// ChipReadRequest is a request body of KUAA's API.
final class ChipReadRequest {
  const ChipReadRequest({
    this.aaSignature,
    this.caKeyId,
    this.caProtocol,
    this.caStatus,
    required this.challengeId,
    required this.dg1,
    this.dg11,
    this.dg12,
    this.dg14,
    this.dg15,
    this.dg2,
    this.efCardAccess,
    this.efCom,
    required this.efSod,
    this.printedMrz,
  });

  /// The chip's INTERNAL AUTHENTICATE response to the issued challenge, as read
  /// from the chip -- tag and length included -- in standard base64. At most
  /// 1024 bytes decoded.
  final String? aaSignature;

  /// The Chip Authentication key the device used, when DG14 lists more than
  /// one.
  final int? caKeyId;

  /// The Chip Authentication protocol the device ran, as the object identifier
  /// DG14 names it.
  final String? caProtocol;

  /// What the device reports about Chip Authentication. The server checks only
  /// that the claim is consistent with an authenticated DG14: the protocol
  /// itself runs on the device.
  ///
  /// One of `completed`, `failed`.
  final String? caStatus;

  /// The challenge issued for this read. It answers one read, once, before it
  /// expires.
  final String challengeId;

  /// DG1, the MRZ, as read, in standard base64. At most 1024 bytes decoded.
  final String dg1;

  /// DG11, additional personal details, when the chip has it, as read from the
  /// chip -- tag and length included -- in standard base64. At most 8192 bytes
  /// decoded.
  final String? dg11;

  /// DG12, additional document details, when the chip has it, as read from the
  /// chip -- tag and length included -- in standard base64. At most 8192 bytes
  /// decoded.
  final String? dg12;

  /// DG14, the Chip Authentication and PACE security infos, as read from the
  /// chip -- tag and length included -- in standard base64. At most 16384 bytes
  /// decoded.
  final String? dg14;

  /// DG15, the Active Authentication public key, as read from the chip -- tag
  /// and length included -- in standard base64. At most 4096 bytes decoded.
  final String? dg15;

  /// DG2, the face image (biometric data, stored sealed), as read from the chip
  /// -- tag and length included -- in standard base64. At most 524288 bytes
  /// decoded.
  final String? dg2;

  /// EF.CardAccess, the PACE infos, as read from the chip -- tag and length
  /// included -- in standard base64. At most 4096 bytes decoded.
  final String? efCardAccess;

  /// EF.COM, as read from the chip -- tag and length included -- in standard
  /// base64. At most 1024 bytes decoded.
  final String? efCom;

  /// EF.SOD, as read, in standard base64. Without it nothing is authenticated.
  /// At most 65536 bytes decoded.
  final String efSod;

  /// The MRZ of the printed page, its lines separated by line breaks, compared
  /// field by field with DG1. It is not stored outside the sealed read and
  /// never answered.
  final String? printedMrz;

  /// The JSON the API takes; a field left null is left out.
  Map<String, Object?> toJson() => {
    'aa_signature': ?aaSignature,
    'ca_key_id': ?caKeyId,
    'ca_protocol': ?caProtocol,
    'ca_status': ?caStatus,
    'challenge_id': challengeId,
    'dg1': dg1,
    'dg11': ?dg11,
    'dg12': ?dg12,
    'dg14': ?dg14,
    'dg15': ?dg15,
    'dg2': ?dg2,
    'ef_card_access': ?efCardAccess,
    'ef_com': ?efCom,
    'ef_sod': efSod,
    'printed_mrz': ?printedMrz,
  };
}

/// The label of the organization's own set of situations a reviewer gave the
/// case, such as "Aguardando compliance". It never changes status,
/// status_market or the decision. Null when the case carries none, or for a key
/// without tag.list.
final class CustomStatus {
  const CustomStatus({
    required this.name,
    required this.slug,
  });

  /// A CustomStatus out of the API's JSON.
  factory CustomStatus.fromJson(Map<String, Object?> json) {
    return CustomStatus(
      name: json['name'] as String,
      slug: json['slug'] as String,
    );
  }

  /// The name the organization gave it.
  final String name;

  /// The custom status's slug: derived from its name when it was created, and
  /// never changed after.
  final String slug;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'name': name,
    'slug': slug,
  };
}

/// A decision on a case. Which engine measured what stays inside; the dossier
/// says what was measured.
final class Decision {
  const Decision({
    required this.decidedAt,
    required this.decidedByKind,
    required this.id,
    required this.outcome,
    required this.policy,
    required this.reasons,
  });

  /// A Decision out of the API's JSON.
  factory Decision.fromJson(Map<String, Object?> json) {
    return Decision(
      decidedAt: json['decided_at'] as String,
      decidedByKind: json['decided_by_kind'] as String,
      id: json['id'] as String,
      outcome: json['outcome'] as String,
      policy: Policy.fromJson(readObject(json['policy'])),
      reasons: readList(json['reasons'], readString),
    );
  }

  final String decidedAt;

  /// engine is the policy engine; reviewer is a person.
  ///
  /// One of `engine`, `reviewer`.
  final String decidedByKind;

  final String id;

  /// What KUAA decided. Engines produce evidence; the decision is KUAA's, by
  /// the pinned policy or a reviewer.
  ///
  /// One of `approved`, `rejected`, `manual_review`, `request_information`.
  final String outcome;

  /// The policy version that produced the decision: its id, version and content
  /// digest.
  final Policy policy;

  /// The stable reason codes behind the outcome.
  final List<String> reasons;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'decided_at': decidedAt,
    'decided_by_kind': decidedByKind,
    'id': id,
    'outcome': outcome,
    'policy': policy.toJson(),
    'reasons': reasons,
  };
}

/// A document of a case: its kind and where it stands. No byte of the file, its
/// artifact or anything read from it leaves.
final class Document {
  const Document({
    required this.capture,
    this.capturedAt,
    this.decision,
    this.documentType,
    required this.id,
    required this.inForce,
    required this.partyId,
    required this.receivedAt,
    required this.requirement,
    this.side,
    required this.status,
  });

  /// A Document out of the API's JSON.
  factory Document.fromJson(Map<String, Object?> json) {
    return Document(
      capture: json['capture'] as String,
      capturedAt: json['captured_at'] as String?,
      decision: readOptional(
        json['decision'],
        (value) => DocumentDecision.fromJson(readObject(value)),
      ),
      documentType: json['document_type'] as String?,
      id: json['id'] as String,
      inForce: json['in_force'] as bool,
      partyId: json['party_id'] as String,
      receivedAt: json['received_at'] as String,
      requirement: json['requirement'] as String,
      side: json['side'] as String?,
      status: json['status'] as String,
    );
  }

  /// One of `document`, `selfie`.
  final String capture;

  /// When the client said it was captured, or null.
  final String? capturedAt;

  /// The reviewer's decision in force about the document, the newest one, or
  /// null while nobody decided. The reviewer's reason never leaves through the
  /// API.
  final DocumentDecision? decision;

  /// The type of a document capture, such as CNH or RG; null for a selfie.
  final String? documentType;

  /// The document row.
  final String id;

  /// False for a document a newer capture replaced or that could not be used.
  final bool inForce;

  /// The party who presented it.
  final String partyId;

  /// When the file was received.
  final String receivedAt;

  /// What the document answers of what the case's workflow requires.
  ///
  /// One of `identity_document`, `selfie`.
  final String requirement;

  /// front, back or single for a document capture; null for a selfie.
  final String? side;

  /// received, processed once its checks ran, refused when it cannot be used,
  /// or superseded when a newer capture replaced it.
  final String status;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'capture': capture,
    'captured_at': capturedAt,
    'decision': decision?.toJson(),
    'document_type': documentType,
    'id': id,
    'in_force': inForce,
    'party_id': partyId,
    'received_at': receivedAt,
    'requirement': requirement,
    'side': side,
    'status': status,
  };
}

/// The reviewer's decision in force about the document, the newest one, or null
/// while nobody decided. The reviewer's reason never leaves through the API.
final class DocumentDecision {
  const DocumentDecision({
