        json['documents'],
        (value) => Document.fromJson(readObject(value)),
      ),
      livemode: json['livemode'] as bool,
    );
  }

  final String caseId;

  /// The documents and selfies of the case, oldest first. The frames of a
  /// liveness capture are not listed.
  final List<Document> documents;

  /// False when the answer comes from the organization's sandbox: synthetic
