}

/// What was checked, what was found and what was decided on a case. Evidence is
/// summarized by what was measured and its result, never by an engine's raw
/// output.
final class Dossier {
  const Dossier({
    required this.checks,
    required this.createdAt,
    required this.currentState,
    required this.decisions,
    required this.documents,
    required this.externalReference,
    required this.findings,
    required this.id,
    required this.kind,
    required this.livemode,
    required this.parties,
    required this.relationships,
    required this.reviews,
    required this.status,
    required this.statusMarket,
    required this.updatedAt,
    this.workflow,
  });

  /// A Dossier out of the API's JSON.
  factory Dossier.fromJson(Map<String, Object?> json) {
    return Dossier(
      checks: readList(
        json['checks'],
        (value) => Check.fromJson(readObject(value)),
      ),
      createdAt: json['created_at'] as String,
      currentState: json['current_state'] as String,
      decisions: readList(
        json['decisions'],
        (value) => Decision.fromJson(readObject(value)),
      ),
      documents: readList(
        json['documents'],
        (value) => Document.fromJson(readObject(value)),
      ),
      externalReference: json['external_reference'] as String,
      findings: readList(
        json['findings'],
        (value) => Finding.fromJson(readObject(value)),
      ),
      id: json['id'] as String,
      kind: json['kind'] as String,
      livemode: json['livemode'] as bool,
      parties: readList(
        json['parties'],
        (value) => DossierParty.fromJson(readObject(value)),
      ),
      relationships: readList(
        json['relationships'],
        (value) => Relationship.fromJson(readObject(value)),
      ),
      reviews: readList(
        json['reviews'],
        (value) => Review.fromJson(readObject(value)),
      ),
      status: json['status'] as String,
      statusMarket: json['status_market'] as String,
      updatedAt: json['updated_at'] as String,
      workflow: readOptional(
        json['workflow'],
        (value) => DossierWorkflow.fromJson(readObject(value)),
      ),
    );
  }

  final List<Check> checks;

  final String createdAt;

  final String currentState;

  /// Every decision taken on the case, oldest first.
  final List<Decision> decisions;

  /// The documents and selfies of the case with the reviewers' decision about
  /// each, oldest first, as GET /v1/cases/{id}/documents lists them.
  final List<Document> documents;

  final String externalReference;

  final List<Finding> findings;

  final String id;

  /// One of `KYC`, `KYB`, `AGE`.
  final String kind;

  /// False when the answer comes from the organization's sandbox: synthetic
  /// data, engine doubles chosen by the documented magic values, nothing billed
  /// and no official source consulted. True in production.
  final bool livemode;

  final List<DossierParty> parties;

  final List<Relationship> relationships;

  final List<Review> reviews;

  /// One of `open`, `processing`, `awaiting_input`, `in_review`, `approved`,
  /// `rejected`, `cancelled`, `expired`.
  final String status;

  /// The status in the vocabulary of the Brazilian KYC market, beside status,
  /// which keeps its values: PROCESSING (open, processing, awaiting_input),
  /// PENDING_OCR (in_review because a document reading check -- OCR or
  /// validation -- failed or timed out), PENDING (in_review, waiting for a
  /// human decision), APPROVED (approved), REPROVED (rejected), BLOCKED
  /// (rejected by the policy's block outcome, such as a confirmed sanctions
  /// match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED
  /// are closed without a decision. It never changes the decision.
  ///
  /// One of `PROCESSING`, `PENDING_OCR`, `PENDING`, `APPROVED`, `REPROVED`,
  /// `BLOCKED`, `CANCELLED`, `EXPIRED`.
  final String statusMarket;

  final String updatedAt;

  /// The workflow run and its steps, or null before the case starts.
  final DossierWorkflow? workflow;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'checks': checks.map((item) => item.toJson()).toList(),
    'created_at': createdAt,
    'current_state': currentState,
    'decisions': decisions.map((item) => item.toJson()).toList(),
    'documents': documents.map((item) => item.toJson()).toList(),
    'external_reference': externalReference,
    'findings': findings.map((item) => item.toJson()).toList(),
    'id': id,
    'kind': kind,
    'livemode': livemode,
    'parties': parties.map((item) => item.toJson()).toList(),
    'relationships': relationships.map((item) => item.toJson()).toList(),
    'reviews': reviews.map((item) => item.toJson()).toList(),
    'status': status,
    'status_market': statusMarket,
    'updated_at': updatedAt,
    'workflow': workflow?.toJson(),
  };
}

/// A party in the dossier. Without party.pii.view the identifier is masked and
/// the names and dates are left out; meta.full_pii says which.
final class DossierParty {
  const DossierParty({
