    this.cnae,
    this.cnpj,
    this.cpf,
    this.fullName,
    required this.id,
    this.identityId,
    required this.kind,
    this.naturezaJuridica,
    this.nomeFantasia,
    required this.primary,
    this.razaoSocial,
    this.situacao,
    this.socialName,
  });

  /// A DossierParty out of the API's JSON.
  factory DossierParty.fromJson(Map<String, Object?> json) {
    return DossierParty(
      birthDate: json['birth_date'] as String?,
      cnae: json['cnae'] as String?,
      cnpj: json['cnpj'] as String?,
      cpf: json['cpf'] as String?,
      fullName: json['full_name'] as String?,
      id: json['id'] as String,
      identityId: json['identity_id'] as String?,
      kind: json['kind'] as String,
      naturezaJuridica: json['natureza_juridica'] as String?,
      nomeFantasia: json['nome_fantasia'] as String?,
      primary: json['primary'] as bool,
      razaoSocial: json['razao_social'] as String?,
      situacao: json['situacao'] as String?,
      socialName: json['social_name'] as String?,
    );
  }

  /// The birth date of a PERSON, when known. Present only for a key with
  /// party.pii.view.
  final String? birthDate;

  /// The main CNAE activity code of a BUSINESS. Present only for a key with
  /// party.pii.view.
  final String? cnae;

  /// The CNPJ of a BUSINESS as text. In full (normalized,
  /// ^[0-9A-Z]{12}[0-9]{2}$) for a key with party.pii.view; otherwise masked,
  /// every character but the two check digits replaced by *, as ************95.
  final String? cnpj;

  /// The CPF of a PERSON as text. In full (11 digits) for a key with
  /// party.pii.view; otherwise masked, every character but the two check digits
  /// replaced by *, as *********25.
  final String? cpf;

  /// The civil name of a PERSON. Present only for a key with party.pii.view.
  final String? fullName;

  /// The party's identifier.
  final String id;

  /// The resolved identity the party was matched to, or null before resolution.
  final String? identityId;

  /// One of `PERSON`, `BUSINESS`.
  final String kind;

  /// The legal nature code of a BUSINESS. Present only for a key with
  /// party.pii.view.
  final String? naturezaJuridica;

  /// The trade name of a BUSINESS. Present only for a key with party.pii.view.
  final String? nomeFantasia;

  /// Whether the party is the primary subject of the case.
  final bool primary;

  /// The registered name of a BUSINESS. Present only for a key with
  /// party.pii.view.
  final String? razaoSocial;

  /// The registration status of a BUSINESS. Present only for a key with
  /// party.pii.view.
  final String? situacao;

  /// The social name of a PERSON, empty when none. Present only for a key with
  /// party.pii.view.
  final String? socialName;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'birth_date': ?birthDate,
    'cnae': ?cnae,
    'cnpj': ?cnpj,
    'cpf': ?cpf,
    'full_name': ?fullName,
    'id': id,
    'identity_id': identityId,
    'kind': kind,
    'natureza_juridica': ?naturezaJuridica,
    'nome_fantasia': ?nomeFantasia,
    'primary': primary,
    'razao_social': ?razaoSocial,
    'situacao': ?situacao,
    'social_name': ?socialName,
  };
}

