/// A summary of one piece of evidence; the engine's raw output never leaves.
final class Evidence {
  const Evidence({
    required this.id,
    required this.measured,
    required this.performedAt,
    required this.result,
    this.score,
  });

  /// A Evidence out of the API's JSON.
  factory Evidence.fromJson(Map<String, Object?> json) {
    return Evidence(
      id: json['id'] as String,
      measured: json['measured'] as String,
      performedAt: json['performed_at'] as String,
      result: json['result'] as String,
      score: readOptional(json['score'], readDouble),
    );
  }

  final String id;

  /// What was measured.
  final String measured;

  final String performedAt;

  /// One of `pass`, `fail`, `inconclusive`, `error`.
  final String result;

