/// Lookup is an object of KUAA's API.
final class Lookup {
  const Lookup({
    this.company,
    required this.cost,
    required this.createdAt,
    required this.document,
    required this.environment,
    required this.id,
    required this.kind,
    required this.legalBasis,
    required this.livemode,
    required this.object,
    this.person,
    required this.provenance,
    required this.purpose,
    required this.reasons,
    required this.ruleVersion,
    required this.screening,
    required this.sources,
    required this.status,
  });

  /// A Lookup out of the API's JSON.
  factory Lookup.fromJson(Map<String, Object?> json) {
    return Lookup(
      company: readOptional(
        json['company'],
        (value) => LookupCompany.fromJson(readObject(value)),
      ),
      cost: LookupCost.fromJson(readObject(json['cost'])),
      createdAt: json['created_at'] as String,
      document: json['document'] as String,
      environment: json['environment'] as String,
      id: json['id'] as String,
      kind: json['kind'] as String,
      legalBasis: json['legal_basis'] as String,
      livemode: json['livemode'] as bool,
      object: json['object'] as String,
      person: readOptional(
        json['person'],
        (value) => LookupPerson.fromJson(readObject(value)),
      ),
      provenance: LookupProvenance.fromJson(readObject(json['provenance'])),
      purpose: json['purpose'] as String,
      reasons: readList(json['reasons'], readString),
      ruleVersion: json['rule_version'] as String,
      screening: LookupScreening.fromJson(readObject(json['screening'])),
      sources: readList(
        json['sources'],
        (value) => LookupSource.fromJson(readObject(value)),
      ),
      status: json['status'] as String,
    );
  }

  /// Present on a business lookup.
  final LookupCompany? company;

  final LookupCost cost;

  final String createdAt;

  /// The CPF or CNPJ, masked.
  final String document;

  /// One of `live`, `sandbox`.
  final String environment;

  final String id;

  /// One of `person`, `business`.
  final String kind;

  /// The LGPD article the purpose is made under, such as lgpd.art7.v.
  final String legalBasis;

  final bool livemode;

  /// One of `lookup`.
  final String object;

  /// Present on a person lookup.
  final LookupPerson? person;

  /// Where each field came from and when, by field name; a field with no value
  /// has no entry.
  final LookupProvenance provenance;

  /// One of `onboarding`, `fraud_prevention`, `legal_obligation`,
  /// `credit_protection`, `contract_execution`.
  final String purpose;

  /// Irregular: cpf_suspended, cpf_cancelled, cpf_null,
  /// cpf_pending_regularization, cnpj_suspended, cnpj_unfit, cnpj_closed,
  /// cnpj_null, deceased, sanctions_confirmed. Inconclusive: situacao_unknown,
  /// obito_unknown, sanctions_possible, not_found, screening_unavailable,
  /// daily_limit_reached (LOOKUP_DAILY_LIMIT; nothing was asked),
  /// bureau_not_enabled, product_disabled, no_token, budget_exceeded,
  /// provider_unavailable. Flagged only: pep, pep_possible, screening_partial
  /// (screening.unavailable names the missing sources), and aml_&lt;reason&gt;
  /// when AML was not answered.
  final List<String> reasons;

  final String ruleVersion;

  final LookupScreening screening;

  final List<LookupSource> sources;

  /// KUAA's conclusion under rule_version: irregular when the situação is a
  /// known one other than REGULAR (CPF) or ATIVA (CNPJ), when the person died,
  /// or when a sanctions list holds the document itself; inconclusive when the
  /// registry could not be read or held nothing, the situação is empty or
  /// unknown, óbito could not be read, a sanctions list holds the name only, or
  /// no list could be read; regular otherwise. A PEP is a reason, not an
  /// irregularity. failed is a lookup GET reads whose processing did not
  /// finish; retrying the same day is answered from the bureau's paid answer.
  ///
  /// One of `regular`, `irregular`, `inconclusive`, `failed`.
  final String status;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'company': ?company?.toJson(),
    'cost': cost.toJson(),
    'created_at': createdAt,
    'document': document,
    'environment': environment,
    'id': id,
    'kind': kind,
    'legal_basis': legalBasis,
    'livemode': livemode,
    'object': object,
    'person': ?person?.toJson(),
    'provenance': provenance.toJson(),
    'purpose': purpose,
    'reasons': reasons,
    'rule_version': ruleVersion,
    'screening': screening.toJson(),
    'sources': sources.map((item) => item.toJson()).toList(),
    'status': status,
  };
}

