/// PartyProfile is an object of KUAA's API.
final class PartyProfile {
  const PartyProfile({
    this.cases,
    this.cnpj,
    this.cpf,
    required this.id,
    this.identity,
    required this.kind,
    required this.livemode,
    required this.monitoring,
    this.name,
    required this.partyIds,
    this.screenings,
    this.tags,
  });

  /// A PartyProfile out of the API's JSON.
  factory PartyProfile.fromJson(Map<String, Object?> json) {
    return PartyProfile(
      cases: readOptional(
        json['cases'],
        (value) => readList(
          value,
          (value) => PartyProfileCase.fromJson(readObject(value)),
        ),
      ),
      cnpj: json['cnpj'] as String?,
      cpf: json['cpf'] as String?,
      id: json['id'] as String,
      identity: readOptional(
        json['identity'],
        (value) => Identity.fromJson(readObject(value)),
      ),
      kind: json['kind'] as String,
      livemode: json['livemode'] as bool,
      monitoring: Monitoring.fromJson(readObject(json['monitoring'])),
      name: json['name'] as String?,
      partyIds: readList(json['party_ids'], readString),
      screenings: readOptional(
        json['screenings'],
        (value) =>
            readList(value, (value) => Screening.fromJson(readObject(value))),
      ),
      tags: readOptional(
        json['tags'],
        (value) => readList(
          value,
          (value) => PartyProfileTag.fromJson(readObject(value)),
        ),
      ),
    );
  }

  /// The cases it takes part in, newest first. Null for a key without
  /// case.list.
  final List<PartyProfileCase>? cases;

  /// The CNPJ of a BUSINESS as text, which may be alphanumeric. In full for a
  /// key with party.pii.view; otherwise masked, every character but the two
  /// check digits replaced by *.
  final String? cnpj;

  /// The CPF of a PERSON as text. In full (11 digits) for a key with
  /// party.pii.view; otherwise masked, every character but the two check digits
  /// replaced by *.
  final String? cpf;

  /// The profile: the id of the first party row of this CPF or CNPJ in the
  /// organization. GET /v1/parties/{id} takes it, or any party id of the same
  /// person or company.
  final String id;

  /// What KUAA verified about the identifier across cases. Null when nothing
  /// was, or for a key without identity.view.
  final Identity? identity;

  /// One of `PERSON`, `BUSINESS`.
  final String kind;

  /// False when the answer comes from the organization's sandbox: synthetic
  /// data, engine doubles chosen by the documented magic values, nothing billed
  /// and no official source consulted. True in production.
  final bool livemode;

  final Monitoring monitoring;

  /// The full name of a person or the razão social of a company, from its
  /// newest party row. Null without party.pii.view.
  final String? name;

  /// Every party row of this CPF or CNPJ in the organization, oldest first.
  final List<String> partyIds;

  /// The latest screening of each list among its party rows. Null for a key
  /// without evidence.view.
  final List<Screening>? screenings;

  /// The tags its party rows carry, without repeats. Null for a key without
  /// tag.list.
  final List<PartyProfileTag>? tags;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'cases': cases?.map((item) => item.toJson()).toList(),
    'cnpj': cnpj,
    'cpf': cpf,
    'id': id,
    'identity': identity?.toJson(),
    'kind': kind,
    'livemode': livemode,
    'monitoring': monitoring.toJson(),
    'name': name,
    'party_ids': partyIds,
    'screenings': screenings?.map((item) => item.toJson()).toList(),
    'tags': tags?.map((item) => item.toJson()).toList(),
  };
}

/// PartyProfileCase is an object of KUAA's API.
final class PartyProfileCase {
