  final String? caseId;

  /// The check a charge was for.
  final String? check;

  /// The ledger entry.
  final String id;

  /// charge for verification work, top_up for credits added, or the wallet
  /// operation kind for anything else, such as a reversal or an adjustment.
  final String kind;

  final String operationId;

  final String? priceKey;

  final String? priceListVersion;

  /// What a top-up or a reversal was recorded as.
  final String? reason;

  /// The workflow step a charge was for.
  final int? stepSeq;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'amount': amount,
    'at': at,
    'balance_after': balanceAfter,
    'case_id': caseId,
    'check': check,
    'id': id,
    'kind': kind,
    'operation_id': operationId,
    'price_key': priceKey,
    'price_list_version': priceListVersion,
    'reason': reason,
    'step_seq': stepSeq,
  };
}

