    return Webhook(
      active: json['active'] as bool,
      createdAt: json['created_at'] as String,
      disabledAt: json['disabled_at'] as String?,
      disabledReason: json['disabled_reason'] as String?,
      events: readList(json['events'], readString),
      id: json['id'] as String,
      name: json['name'] as String,
      url: json['url'] as String,
    );
  }

  /// Whether events are delivered. An endpoint turned off keeps its deliveries
  /// waiting until it is turned on.
  final bool active;

  final String createdAt;

  final String? disabledAt;

  /// Why the endpoint was turned off: consecutive_failures when its deliveries
  /// kept giving up, or what the person who turned it off wrote.
  final String? disabledReason;

  final List<String> events;

  /// The endpoint identifier.
  final String id;

  final String name;

  /// The https:// address the deliveries go to.
  final String url;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'active': active,
    'created_at': createdAt,
    'disabled_at': disabledAt,
    'disabled_reason': disabledReason,
    'events': events,
    'id': id,
    'name': name,
    'url': url,
  };
}

