/// The body of a webhook delivery. It carries no personal data; read the case
/// through the API.
final class WebhookEvent {
  const WebhookEvent({
    required this.data,
    required this.datacontenttype,
    required this.id,
    required this.source,
    required this.specversion,
    required this.subject,
    required this.time,
    required this.type,
  });

  /// A WebhookEvent out of the API's JSON.
  factory WebhookEvent.fromJson(Map<String, Object?> json) {
    return WebhookEvent(
      data: WebhookEventData.fromJson(readObject(json['data'])),
      datacontenttype: json['datacontenttype'] as String,
      id: json['id'] as String,
      source: json['source'] as String,
      specversion: json['specversion'] as String,
      subject: json['subject'] as String,
      time: json['time'] as String,
      type: json['type'] as String,
    );
  }

  final WebhookEventData data;

  /// One of `application/json`.
  final String datacontenttype;

  /// The event id: the same on every delivery of the event and on every retry.
  /// Deduplicate on it.
  final String id;

  /// urn:kuaa:tenant: and the tenant the event happened in.
  final String source;

  /// One of `1.0`.
  final String specversion;

  /// cases/ and the case id.
  final String subject;

  final String time;

  /// One of `case.created`, `case.updated`, `check.completed`,
  /// `decision.recorded`, `review.recorded`, `capture_session.finished`,
  /// `document.decided`, `capture_session.opened`,
  /// `capture_session.consent_given`, `capture_session.document_submitted`,
  /// `capture_session.selfie_submitted`, `capture_session.expired`,
  /// `capture_session.revoked`.
  final String type;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'data': data.toJson(),
    'datacontenttype': datacontenttype,
    'id': id,
    'source': source,
    'specversion': specversion,
    'subject': subject,
    'time': time,
    'type': type,
  };
}

/// WebhookEventData is an object of KUAA's API.
final class WebhookEventData {
  const WebhookEventData({
    this.captureSessionId,
    required this.caseId,
    this.checkId,
    this.decision,
    this.decisionId,
    this.documentDecisionId,
    this.documentId,
    this.documentSide,
    this.documentType,
    required this.environment,
    required this.eventId,
    this.finishedAt,
    required this.livemode,
    required this.occurredAt,
    this.parentCaseId,
    this.requirement,
    this.reviewId,
    required this.status,
    this.statusMarket,
    this.step,
    required this.tenantId,
    required this.type,
  });

  /// A WebhookEventData out of the API's JSON.
  factory WebhookEventData.fromJson(Map<String, Object?> json) {
    return WebhookEventData(
      captureSessionId: json['capture_session_id'] as String?,
      caseId: json['case_id'] as String,
      checkId: json['check_id'] as String?,
      decision: json['decision'] as String?,
      decisionId: json['decision_id'] as String?,
      documentDecisionId: json['document_decision_id'] as String?,
      documentId: json['document_id'] as String?,
      documentSide: json['document_side'] as String?,
      documentType: json['document_type'] as String?,
      environment: json['environment'] as String,
      eventId: json['event_id'] as String,
      finishedAt: json['finished_at'] as String?,
      livemode: json['livemode'] as bool,
      occurredAt: json['occurred_at'] as String,
      parentCaseId: json['parent_case_id'] as String?,
      requirement: json['requirement'] as String?,
      reviewId: json['review_id'] as String?,
      status: json['status'] as String,
      statusMarket: json['status_market'] as String?,
      step: json['step'] as String?,
      tenantId: json['tenant_id'] as String,
      type: json['type'] as String,
    );
  }

  /// Present on every capture_session.* event: the hosted capture session, as
  /// answered when its link was issued.
  final String? captureSessionId;

  final String caseId;

  /// Present on check.completed.
  final String? checkId;

  /// Present on document.decided: what the reviewer decided about the document.
  /// It never decides the case; the reviewer's reason is not sent.
  ///
  /// One of `approved`, `rejected`, `rerequested`.
  final String? decision;

  /// Present on decision.recorded.
  final String? decisionId;

  /// Present on document.decided: the decision a reviewer recorded about one
  /// document.
  final String? documentDecisionId;

  /// Present on document.decided: the document the decision is about, as GET
  /// /v1/cases/{id}/documents lists it.
  final String? documentId;

  /// Present on document.decided for a document capture: front, back or single.
  /// Absent for a selfie.
  final String? documentSide;

  /// Present on document.decided for a document capture: its type, such as CNH
  /// or RG. Absent for a selfie.
  final String? documentType;

  /// The environment of the tenant the event happened in. A sandbox event is
  /// about synthetic data and engine doubles.
  ///
  /// One of `live`, `sandbox`.
  final String environment;

  /// The event id, the same as the envelope's id.
  final String eventId;

  /// Present on capture_session.finished: when the person sent the capture.
  final String? finishedAt;

  /// False for an event of the organization's sandbox, true in production.
  final bool livemode;

  final String occurredAt;

  /// Present on case.created and case.updated of a child case: the case whose
  /// workflow opened it. Absent otherwise.
  final String? parentCaseId;

  /// Present on document.decided: what the document answers.
  ///
  /// One of `identity_document`, `selfie`.
  final String? requirement;

  /// Present on review.recorded.
  final String? reviewId;

  /// What the event left behind: the case's status for case.*, the check's for
  /// check.completed, the outcome for decision.recorded, the reviewer's action
  /// for review.recorded, finished for capture_session.finished, the session's
  /// status after the event (active, expired or revoked) for the other
  /// capture_session.* events, and the reviewer's decision about the document
  /// (approved, rejected or rerequested) for document.decided.
  final String status;

  /// Present on case.created, case.updated and capture_session.finished: The
  /// status in the vocabulary of the Brazilian KYC market, beside status, which
  /// keeps its values: PROCESSING (open, processing, awaiting_input),
  /// PENDING_OCR (in_review because a document reading check -- OCR or
  /// validation -- failed or timed out), PENDING (in_review, waiting for a
  /// human decision), APPROVED (approved), REPROVED (rejected), BLOCKED
  /// (rejected by the policy's block outcome, such as a confirmed sanctions
  /// match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED
  /// are closed without a decision. It never changes the decision.
  ///
  /// One of `PROCESSING`, `PENDING_OCR`, `PENDING`, `APPROVED`, `REPROVED`,
  /// `BLOCKED`, `CANCELLED`, `EXPIRED`.
  final String? statusMarket;

  /// Present on capture_session.consent_given, .document_submitted and
  /// .selfie_submitted: the step of the hosted capture the person finished.
  ///
  /// One of `consent`, `document`, `selfie`.
  final String? step;

  final String tenantId;

  /// One of `case.created`, `case.updated`, `check.completed`,
  /// `decision.recorded`, `review.recorded`, `capture_session.finished`,
  /// `document.decided`, `capture_session.opened`,
  /// `capture_session.consent_given`, `capture_session.document_submitted`,
  /// `capture_session.selfie_submitted`, `capture_session.expired`,
  /// `capture_session.revoked`.
  final String type;

  /// The JSON the API answers.
  Map<String, Object?> toJson() => {
    'capture_session_id': ?captureSessionId,
    'case_id': caseId,
    'check_id': ?checkId,
    'decision': ?decision,
    'decision_id': ?decisionId,
    'document_decision_id': ?documentDecisionId,
    'document_id': ?documentId,
    'document_side': ?documentSide,
    'document_type': ?documentType,
    'environment': environment,
    'event_id': eventId,
    'finished_at': ?finishedAt,
    'livemode': livemode,
    'occurred_at': occurredAt,
    'parent_case_id': ?parentCaseId,
    'requirement': ?requirement,
    'review_id': ?reviewId,
    'status': status,
    'status_market': ?statusMarket,
    'step': ?step,
    'tenant_id': tenantId,
    'type': type,
  };
}

